mapper.sql:
SELECT distinct CI.ID, CI.CREATE_TIME, CI.MODIFY_TIME, CI.REC_VER, CI.LOGIC_DEL, CI.BUILD_IN, CI.NAME, CI.FILE_ID, CI.ICON_PARTITION, CI.ORDER_NUM, CI.REMARK, SO.ORIGINAL_NAME AS FILE_NAME, SO.URL FROM common_icon CI LEFT JOIN sys_oss so on so.id = ci.FILE_ID WHERE 1 = 1 AND CI.LOGIC_DEL = 0
AND CI.ID = #{commonIconDto.id}
AND SO.ID = #{commonIconDto.fileId}
ORDER BY CI.CREATE_TIME DESC, CI.MODIFY_TIME DESC

mapper.select:
SELECT MAX(CI.ORDER_NUM)
FROM common_icon CI
WHERE CI.ICON_PARTITION = #{iconPartition}
